//! Generated by `scripts/gen_benches.py`: times `lean_runtime::semantics::array::get_bang`; the
//! native twin is `benches/native/Bench/ArrayGetBang.lean`.
//! indices in bounds: out of bounds both sides print a panic message

#![allow(unused_parens, unused_imports, unused_variables, unused_mut)]
#![allow(
    clippy::double_parens,
    clippy::unnecessary_cast,
    clippy::redundant_closure
)]
#![allow(clippy::identity_op, clippy::let_and_return)]

use lean_runtime::semantics::array;
use lean_runtime_bench::*;
use std::hint::black_box;

#[inline(never)]
fn kernel(inp: &Vec<u64>, n: u64) -> u64 {
    let xs = &inp[..];
    let (mut x, mut acc) = (SEED, 0u64);
    for _ in 0..n {
        x = step(x);
        acc = mix(
            acc,
            match array::get_bang(xs.len(), nat_unbox(nat_box(x >> 52))) {
                Ok(k) => nat_unbox(xs[k]),
                Err(o) => {
                    lean_panic(o.message());
                    0
                }
            },
        );
    }
    acc
}

fn main() {
    run(|| nat_words(), kernel)
}
